typedef char QXP_D3DCAPS9_size_must_be_304[
    sizeof(QXP_D3DCAPS9) == 304 ? 1 : -1];
/* The size assertion alone does not pin the layout: a transposed or missing
 * field keeps the total at 304 bytes while moving every later field.  Under
 * DDI v3 that is invisible because the runtime derives its own capability
 * block from caps8, but under v4 the runtime consumes this structure
 * directly, so a layout slip would silently corrupt every capability it
 * reads.  These offsets are checked against d3d9caps.h and cover the fields
 * the runtime's format-list builder actually consults, plus the shader and
 * stream fields. */
typedef char QXP_D3DCAPS9_Caps_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, Caps) == 0x08 ? 1 : -1];
typedef char QXP_D3DCAPS9_Caps3_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, Caps3) == 0x10 ? 1 : -1];
typedef char QXP_D3DCAPS9_DevCaps_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, DevCaps) == 0x1c ? 1 : -1];
typedef char QXP_D3DCAPS9_RasterCaps_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, RasterCaps) == 0x24 ? 1 : -1];
typedef char QXP_D3DCAPS9_ShadeCaps_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, ShadeCaps) == 0x38 ? 1 : -1];
typedef char QXP_D3DCAPS9_TextureOpCaps_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, TextureOpCaps) == 0x90 ? 1 : -1];
typedef char QXP_D3DCAPS9_MaxStreams_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, MaxStreams) == 0xbc ? 1 : -1];
typedef char QXP_D3DCAPS9_VertexShaderVersion_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, VertexShaderVersion) == 0xc4 ? 1 : -1];
typedef char QXP_D3DCAPS9_PixelShaderVersion_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, PixelShaderVersion) == 0xcc ? 1 : -1];
typedef char QXP_D3DCAPS9_DevCaps2_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, DevCaps2) == 0xd4 ? 1 : -1];
typedef char QXP_D3DCAPS9_NumSimultaneousRTs_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, NumSimultaneousRTs) == 0xf0 ? 1 : -1];
typedef char QXP_D3DCAPS9_VS20Caps_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, VS20Caps) == 0xf8 ? 1 : -1];
typedef char QXP_D3DCAPS9_PS20Caps_offset[
    FIELD_OFFSET(QXP_D3DCAPS9, PS20Caps) == 0x108 ? 1 : -1];
typedef char QXP_D3D_matrix_layout_must_match[
    sizeof(D3DMATRIX) == sizeof(QXP_D3D_MATRIX) ? 1 : -1];
typedef char QXP_D3D_material_layout_must_match[
    sizeof(D3DMATERIAL7) == sizeof(QXP_D3D_MATERIAL) ? 1 : -1];
typedef char QXP_D3D_light_layout_must_match[
    sizeof(D3DLIGHT7) == sizeof(QXP_D3D_LIGHT) ? 1 : -1];
typedef char QXP_D3D_copy_format_values_must_match[
    D3DFMT_R5G6B5 == QXP_D3D_COPY_FORMAT_R5G6B5 &&
    D3DFMT_A8R8G8B8 == QXP_D3D_COPY_FORMAT_A8R8G8B8 &&
    D3DFMT_X8R8G8B8 == QXP_D3D_COPY_FORMAT_X8R8G8B8 &&
    D3DFMT_R5G6B5 == QXP_D3D_TEXBLT_FORMAT_R5G6B5 &&
    D3DFMT_A8R8G8B8 == QXP_D3D_TEXBLT_FORMAT_A8R8G8B8 &&
    D3DFMT_X8R8G8B8 == QXP_D3D_TEXBLT_FORMAT_X8R8G8B8 ? 1 : -1];
typedef char QXP_D3D_texblt_record_layout_must_match[
    sizeof(D3DNTHAL_DP2TEXBLT) == sizeof(QXP_D3D_TEXBLT_RECORD) &&
    FIELD_OFFSET(D3DNTHAL_DP2TEXBLT, dwDDDestSurface) ==
        offsetof(QXP_D3D_TEXBLT_RECORD, destination_handle) &&
    FIELD_OFFSET(D3DNTHAL_DP2TEXBLT, dwDDSrcSurface) ==
        offsetof(QXP_D3D_TEXBLT_RECORD, source_handle) &&
    FIELD_OFFSET(D3DNTHAL_DP2TEXBLT, pDest) ==
        offsetof(QXP_D3D_TEXBLT_RECORD, destination_x) &&
    FIELD_OFFSET(D3DNTHAL_DP2TEXBLT, rSrc) ==
        offsetof(QXP_D3D_TEXBLT_RECORD, source_left) &&
    FIELD_OFFSET(D3DNTHAL_DP2TEXBLT, dwFlags) ==
        offsetof(QXP_D3D_TEXBLT_RECORD, flags) ? 1 : -1];

