/* Mirrors D3DHAL_DP2BLT (d3dhal.h), which the DX8 XPDM headers compile out.
 * The D3D9 runtime emits it for StretchRect and for its own back-buffer
 * copies, and it cannot emulate the operation itself: the surfaces are
 * driver-managed and only the driver knows where they live. */
typedef struct qxp_d3d9_dp2_blt {
    DWORD dwSource;
    RECTL rSource;
    DWORD dwSourceMipLevel;
    DWORD dwDest;
    RECTL rDest;
    DWORD dwDestMipLevel;
    DWORD Flags;
} QXP_D3D9_DP2_BLT;
#define QXP_D3D9_DP2BLT_POINT 0x00000001UL
#define QXP_D3D9_DP2BLT_LINEAR 0x00000002UL

