typedef struct qxp_d3d_surface_entry {
    DWORD handle;
    /* Scalar copy of the live wrapper handle.  Cube/mip reference entries
     * intentionally keep handle zero, but DXG can free their surface locals
     * without a DestroySurface callback, so runtime lookup must never recover
     * the handle later by dereferencing a historical wrapper. */
    DWORD runtime_handle;
    /* Stable scalar identity of the DirectDraw global backing captured while
     * the wrapper is live.  A retained reference entry may see its numeric
     * handle reused; only the same global identity may preserve incarnation,
     * generation, texture name, and authority across a wrapper replacement. */
    ULONG_PTR global_identity;
    PDD_DIRECTDRAW_LOCAL owner;
    PDD_SURFACE_LOCAL surface;
    DWORD texture_name;
    DWORD chain_texture_name;
    DWORD generation;
    /* Permanent, never-zero identity of the surface object that currently
     * owns this slot.  It never advances while the same live object keeps the
     * slot, so an SM2 draw can reject a resource that was torn down and
     * re-registered even when its owner-scoped handle is reused. */
    ULONGLONG incarnation;
    /* While a last-context recreation epoch remains open, a different-global
     * wrapper may replace this entry exactly once through that epoch.  After
     * first DP2 closes the window, later authoritative handle reuse is an
     * ordinary fresh recreation with no preserved authority. */
    DWORD recreation_epoch;
    BOOL recreation_consumed;
    DWORD uploaded_generation;
    /* Stride-sampled checksum of the guest backing captured by the last
     * texture upload.  XP's D3D9 runtime can fill texture memory through
     * its own video-memory mapping without any Lock/Unlock DDI, leaving
     * uploaded_generation == generation while the bytes changed; the
     * bind-time freshness check compares this against a fresh checksum to
     * catch such silent writes. */
    DWORD upload_checksum;
    /* A scratch transaction never mutates the current name before commit.
     * baseline_valid says that name is a complete reusable image; failed with
     * no baseline refuses ordinary preparation until retry or a CPU write. */
    BOOL texblt_baseline_valid;
    BOOL texblt_failed_without_baseline;
    /* The newest image of this surface lives in the host GL texture (written
     * by an accelerated surface copy); guest video memory is stale until a
     * readback completes. host_write_epoch counts accelerated writes so a
     * readback result is never attributed to a later host write. */
    BOOL host_authoritative;
    BOOL cpu_authoritative;
    DWORD cpu_presented_generation;
    DWORD host_write_epoch;
    ULONG_PTR palette_context_handle;
    DWORD palette_handle;
    DWORD palette_flags;
    DWORD lock_flags;
    BOOL lock_active;
    BOOL lock_preparing;
    BOOL readback_decision_pending;
    DWORD readback_decision_generation;
    DWORD readback_decision_epoch;
    DWORD readback_decision_texture;
    BOOL owner_teardown_pending;
    /* Exact nonwrapping Unlock transaction that blocks a newer Lock until
     * old-lock clearing, presentation classification, and generation
     * publication are complete.  destroy_active is the reciprocal reservation
     * held across DestroySurface readback and final exact revalidation. */
    DWORD unlock_reservation;
    BOOL destroy_active;
#ifdef QXP_DIAGNOSTIC_AUTHORITY
    /* Diagnostic: last game-process shared mapping base handed out by Lock
     * for this surface, and the process that owns it.  Lets the upload
     * probe compare what the game wrote against what the driver's own
     * framebuffer mapping reads back. */
    FLATPTR lock_mapping_base;
    ULONG lock_mapping_process;
    ULONG lock_count;
#endif
} QXP_D3D_SURFACE_ENTRY;

