typedef QXP_D3D9_DRAW_OWNER_GATE QXP_D3D_OWNER_TEARDOWN_BARRIER;
typedef QXP_D3D9_DRAW_OWNER_GATE_TOKEN QXP_D3D_OWNER_OPERATION_TOKEN;

#define QXP_D3D_MAX_RETIRED_TEXTURES QXP_D3D_MAX_SURFACES

static volatile LONG qxp_d3d_table_lock;
static QXP_D3D_SURFACE_ENTRY qxp_d3d_surfaces[QXP_D3D_MAX_SURFACES];
/* Module-lifetime, nonwrapping, never-zero surface incarnation clock.  It is
 * assigned under qxp_d3d_table_lock and is never reset, so incarnations remain
 * globally unique for the life of the driver. */
static ULONGLONG qxp_d3d_surface_incarnation_clock;
/* Module-lifetime, nonwrapping identity for exact Lock/Unlock publication.
 * Exhaustion refuses tracked Lock/Unlock progress rather than reopening ABA. */
static DWORD qxp_d3d_unlock_reservation_clock;
static QXP_D3D_CONTEXT qxp_d3d_contexts[QXP_D3D_MAX_CONTEXTS];
/* One cache for every context.  Its key carries the owner identity, so two
 * devices can never collide and two contexts on one device correctly share a
 * program.  Per-context copies would have cost 64x the memory to hold the
 * same handful of programs.  Access is serialized by the same table lock the
 * snapshot itself takes. */
static QXP_D3D9_DRAW_PREPARE_CACHE qxp_d3d9_prepare_cache;
/* A last-context teardown may precede DXG publishing fresh wrappers.  The
 * epoch is owner-scoped, claimed by exactly one newly reserved context, and
 * never grants authority preservation across a different global identity. */
static DWORD qxp_d3d_recreation_epoch_clock;
static QXP_D3D_RECREATION_WINDOW
    qxp_d3d_recreation_windows[QXP_D3D_MAX_CONTEXTS];
/* D3dDestroyDDLocal is terminal for one local owner, while XP may attach many
 * local owners to the same device-global DirectDraw object.  This global gate
 * counts dereferencing surface callbacks, closes admission during one terminal
 * teardown, drains every admitted callback, and is reclaimed at completion.
 * Capacity or count corruption closes this boundary permanently rather than
 * exposing stale pointers. */
static QXP_D3D_OWNER_TEARDOWN_BARRIER
    qxp_d3d_owner_teardown_barriers[QXP_D3D_MAX_SURFACES];
static BOOL qxp_d3d_owner_teardown_barriers_closed;
/* Old host names are quarantined after atomic TEXBLT publication.  They are
 * never reused or deleted while the owner session remains live, because host
 * name consumers outside TEXBLT do not all participate in one reader gate.
 * Monotonic adjacent names share an interval so sustained updates do not
 * consume one table slot per publication. */
static QXP_D3D_RETIRED_TEXTURE
    qxp_d3d_retired_textures[QXP_D3D_MAX_RETIRED_TEXTURES];
static QXP_D3D9_SHADER_OBJECT_TABLE qxp_d3d9_shader_objects;
static QXP_D3D_PIXEL_SHADER_ENTRY
    qxp_d3d_pixel_shaders[QXP_D3D_MAX_PIXEL_SHADERS];
static QXP_D3D_PIXEL_SHADER_CACHE_ENTRY
    qxp_d3d_pixel_shader_cache[QXP_D3D_PS_CACHE_SIZE];
static DWORD qxp_ps_cache_lru_clock;
static QXP_D3D_VERTEX_SHADER_ENTRY
    qxp_d3d_vertex_shaders[QXP_D3D_MAX_VERTEX_SHADERS];
static QXP_D3D_VERTEX_SHADER_CACHE_ENTRY
    qxp_d3d_vertex_shader_cache[QXP_D3D_VS_CACHE_SIZE];
static DWORD qxp_vs_cache_lru_clock;
static QXP_D3D_PALETTE_ENTRY qxp_d3d_palettes[QXP_D3D_MAX_PALETTES];
static volatile LONG qxp_next_pixel_program = 0x01000000L;
static volatile LONG qxp_next_vertex_program = 0x03000000L;

/* The IR and emitter metadata are much too large for the XP kernel stack.
 * A table-lock-protected one-at-a-time gate makes this fixed workspace safe
 * without adding allocations beyond the packed GLSL source request. */
static BOOL qxp_d3d9_sm2_selftest_active;
static QXP_SHADER_IR qxp_d3d9_sm2_selftest_ir;
static QXP_VERTEX_SHADER_GLSL_METADATA qxp_d3d9_sm2_selftest_vs_metadata;
static QXP_PIXEL_SHADER_GLSL_METADATA qxp_d3d9_sm2_selftest_ps_metadata;

