    QxpDebugValue(context->profile_indexed_compact_layout_calls);
    QxpDebug("QXPDISP PERF INDEXED PROJECTED CALLS");
    QxpDebugValue(context->profile_indexed_projected_calls);
    QxpDebug("QXPDISP PERF INDEXED RAW PRELIT CALLS");
    QxpDebugValue(context->profile_indexed_raw_prelit_calls);
    QxpDebug("QXPDISP PERF INDEXED RAW ELIGIBLE CALLS");
    QxpDebugValue(context->profile_indexed_raw_eligible_calls);
    QxpDebug("QXPDISP PERF INDEXED RAW PACKETS");
