    primitive_size = qxp_d3d_transport_primitive_size(draw->primType);
    source_vertex_bytes = layout.vertex_bytes;
    stride = qxp_d3d_effective_stream0_stride(context, data);
    if (!stride || (!fixed && stride < source_vertex_bytes)) return FALSE;
    if (!total_indices) return TRUE;
    if (source_indices >
            (0xffffffffUL - draw->StartIndexOffset) /
                context->index_stride) return FALSE;
    required_index_bytes = draw->StartIndexOffset +
                           source_indices * context->index_stride;
    if (!qxp_d3d_resolve_surface_source(
            context, data, context->index_handle, required_index_bytes,
            &index_base, &index_bytes) ||
        required_index_bytes > index_bytes) return FALSE;

