    draw_request->cull_mode = 1;
    draw_request->fill_mode = 3;
    draw_request->shade_mode = 2;
    draw_request->point_size_bits = 0x3f800000UL;
    draw_request->point_size_min_bits = 0x3f800000UL;
    draw_request->point_size_max_bits = 0x42800000UL;
    draw_request->point_scale_a_bits = 0x3f800000UL;
    draw_request->color_write_enable = 0x0fUL;
