    draw_request->texture1_name = multi_texture_name;
    draw_request->texture1_address_u = D3DTADDRESS_CLAMP;
    draw_request->texture1_address_v = D3DTADDRESS_CLAMP;
    draw_request->texture1_mag_filter = D3DTEXF_POINT;
    draw_request->texture1_min_filter = D3DTEXF_POINT;
    draw_request->texture1_mip_filter = D3DTEXF_NONE;
    draw_request->texture1_max_mip_level = 0;
