    qxp_dd_zero(&qxp_d3d9_sm2_selftest_vs_metadata,
                sizeof(qxp_d3d9_sm2_selftest_vs_metadata));
    vertex_bytes = 0;
    result->stage = QXP_D3D9_SM2_TEXTURE_STAGE_SCISSOR_VS_EMIT;
